    "space.pro.design":  { en: "The page and frame viewer is Pro. The free version shows the picture saved in the file and an info card.", vi: "Trình xem từng trang, từng frame là Pro. Bản miễn phí hiện ảnh lưu sẵn trong file và thẻ thông tin." },
    "space.pro.rive":    { en: "Rive in Space is Pro. Rive thumbnails in the grid stay free.", vi: "Xem Rive bằng Space là Pro. Thumbnail Rive trong lưới vẫn miễn phí." },
    "space.pro.model":   { en: "Turning the model is Pro. The free version shows the thumbnail and an info card.", vi: "Xoay model là Pro. Bản miễn phí hiện thumbnail và thẻ thông tin." },
    "space.pro.project": { en: "Comps, timelines and used or missing footage are Pro. The free version shows the info card and the picture saved in the project.", vi: "Comp, timeline và footage được dùng hay bị thiếu là Pro. Bản miễn phí hiện thẻ thông tin và ảnh lưu sẵn trong project." },
    "space.pro.code":    { en: "The code card is free. Copy Image and Save PNG are Pro.", vi: "Thẻ code miễn phí. Copy Image và Save PNG là Pro." },
    "space.pro.archive": { en: "The list of what's inside is free. Browsing deeper and previewing the files inside are Pro.", vi: "Danh sách file bên trong là miễn phí. Duyệt sâu và xem trước file bên trong là Pro." },
    "space.where":    { en: "On Mac. Coming to Windows and Linux.", vi: "Có trên Mac. Sắp có cho Windows và Linux." },
