    "space.video.d":  { en: "A real player: play, step frames, change speed, trim. In the grid, hover over a video to scrub it without opening it.",
                        vi: "Player thật: phát, bước từng frame, đổi tốc độ, trim. Ở dạng lưới, rê chuột qua video để tua mà không cần mở." },
    "space.video.f":  { en: "MP4 · MOV · ProRes · HEVC · MKV · WebM · MXF · AVI · MTS", vi: "MP4 · MOV · ProRes · HEVC · MKV · WebM · MXF · AVI · MTS" },
    "space.photo":    { en: "Photos", vi: "Ảnh" },
    "space.photo.d":  { en: "Camera RAW opens as a full picture with its camera, lens and exposure. HEIC, TIFF, PNG and the rest too.",
                        vi: "Ảnh RAW mở thành ảnh đầy đủ, kèm máy ảnh, ống kính và thông số phơi sáng. HEIC, TIFF, PNG và các loại khác cũng vậy." },
    "space.photo.f":  { en: "RAW (NEF · CR3 · ARW · RAF · DNG …) · HEIC · JPEG · PNG · TIFF · WebP · GIF", vi: "RAW (NEF · CR3 · ARW · RAF · DNG …) · HEIC · JPEG · PNG · TIFF · WebP · GIF" },
    "space.design":   { en: "Design & PDF", vi: "Thiết kế & PDF" },
    "space.design.d": { en: "Photoshop layers you can switch on and off, Figma frames, Affinity documents with their fonts and linked files, PDFs page by page. Without Photoshop, Figma or Affinity.",
                        vi: "Layer Photoshop bật tắt được, frame Figma, tài liệu Affinity kèm font và file liên kết, PDF từng trang. Không cần Photoshop, Figma hay Affinity." },
    "space.design.f": { en: "Photoshop .psd .psb · Figma .fig · Affinity .af .afdesign .afphoto .afpub · PDF", vi: "Photoshop .psd .psb · Figma .fig · Affinity .af .afdesign .afphoto .afpub · PDF" },
    "space.motion":   { en: "Motion & 3D", vi: "Motion & 3D" },
    "space.motion.d": { en: "Lottie with play, pause, scrub and speed. Rive that answers your mouse. 3D models you can turn. After Effects projects with their comps, timeline, a sketch of the frame and sound.",
                        vi: "Lottie có phát, dừng, tua và đổi tốc độ. Rive phản hồi theo chuột. Model 3D xoay được. Project After Effects kèm comp, timeline, bản phác khung hình và âm thanh." },
    "space.motion.f": { en: "Lottie .json .lottie · Rive .riv · glTF / GLB · OBJ · FBX · USD · Blender and Cinema 4D thumbnails · After Effects .aep", vi: "Lottie .json .lottie · Rive .riv · glTF / GLB · OBJ · FBX · USD · thumbnail Blender và Cinema 4D · After Effects .aep" },
    "space.edit":     { en: "Editing", vi: "Dựng phim" },
    "space.edit.d":   { en: "Premiere Pro, DaVinci Resolve, Final Cut, Filmora and VEGAS projects open with their timelines, media and the frame at the playhead. Templates show their controls and a preview.",
                        vi: "Project Premiere Pro, DaVinci Resolve, Final Cut, Filmora và VEGAS mở ra với timeline, media và khung hình tại đầu phát. Template hiện các thông số và bản xem trước." },
    "space.edit.f":   { en: "Premiere .prproj · Resolve .drp .dra · Final Cut .fcpxml .fcpbundle · Filmora .wfp · VEGAS .veg · .mogrt · Resolve .setting .drfx · Apple Motion and Final Cut templates", vi: "Premiere .prproj · Resolve .drp .dra · Final Cut .fcpxml .fcpbundle · Filmora .wfp · VEGAS .veg · .mogrt · Resolve .setting .drfx · template Apple Motion và Final Cut" },
    "space.code":     { en: "Code & archives", vi: "Code & file nén" },
    "space.code.d":   { en: "Code on a clean card with syntax colours, ready to copy or save as a picture. Archives show what's inside without extracting them.",
                        vi: "Code trên một tấm thẻ gọn đẹp, có màu cú pháp, sẵn để chép hoặc lưu thành ảnh. File nén cho xem bên trong mà không cần giải nén." },
    "space.code.f":   { en: "JavaScript · TypeScript · Python · Swift · JSON · YAML · Shell · After Effects .jsx · ZIP · RAR · 7z · TAR", vi: "JavaScript · TypeScript · Python · Swift · JSON · YAML · Shell · After Effects .jsx · ZIP · RAR · 7z · TAR" },


