    "find.results":   { en: "{n} results", vi: "{n} kết quả" },
    "find.type":      { en: "Type here to search the demo files", vi: "Gõ vào đây để tìm trong các file mẫu" },
    "find.p1.t":      { en: "Names as you type", vi: "Tên file theo từng phím" },
    "find.p1.d":      { en: "An index of every file name in your Home folder, kept on your Mac. In our tests 500,000 names answer every key in under 16 ms. Typos and missing accents still match.",
                        vi: "Một chỉ mục tên của mọi file trong thư mục Home, lưu ngay trên máy. Khi thử với 500.000 tên, mỗi phím có kết quả dưới 16 ms. Gõ sai hay thiếu dấu vẫn ra." },
    "find.p2.t":      { en: "Spoken words", vi: "Lời nói" },
    "find.p2.d":      { en: "Type said: to search what is said in your clips that have a transcript. Every sentence is listed with its time, and Return plays the clip from there.",
                        vi: "Gõ said: để tìm theo lời nói trong các clip đã có transcript. Mỗi câu hiện kèm thời điểm, bấm Return là phát clip từ đúng câu đó." },
    "find.p3.t":      { en: "Chips", vi: "Chip điều kiện" },
    "find.p3.d":      { en: "kind:video, ext:mov, tag:Red or in:Footage turn into chips that narrow the search. ⌘S keeps it as a Smart Folder.",
                        vi: "kind:video, ext:mov, tag:Red hay in:Footage biến thành chip để thu hẹp kết quả. ⌘S lưu lại thành Smart Folder." },
    "find.p4.t":      { en: "Colour <span class=\"pro-badge\">PRO</span>", vi: "Màu sắc <span class=\"pro-badge\">PRO</span>" },
    "find.p4.d":      { en: "Pick one of 12 colours, Custom… or the eyedropper, and see how much of each picture is that colour. Two colours find pictures with both. Part of the Visual tab.",
                        vi: "Chọn một trong 12 màu, Custom… hoặc ống hút màu, và xem mỗi ảnh có bao nhiêu phần màu đó. Chọn hai màu để tìm ảnh có cả hai. Nằm trong tab Visual." },
    "find.p5.t":      { en: "Advanced", vi: "Advanced" },
    "find.p5.d":      { en: "Size, date, ratio, frame size, rating, tags, folders and duplicates: soft chips in groups that fold, with the results counted as you change them.",
                        vi: "Dung lượng, ngày, tỉ lệ khung, kích thước khung hình, số sao, tag, thư mục và file trùng: các chip trong từng nhóm gập mở được, kết quả đếm lại ngay khi bạn đổi." },
    "find.p6.t":      { en: "External drives", vi: "Ổ cắm ngoài" },
    "find.p6.d":      { en: "Plug a drive in and ⌘K offers to index it. From then on its files show up as you type, and they leave the results the moment you eject it.",
                        vi: "Cắm ổ vào là ⌘K đề nghị lập chỉ mục. Từ đó file trong ổ hiện ra khi bạn gõ, và rời khỏi kết quả ngay khi bạn tháo ổ." },
    "find.visual":    { en: "The Visual tab: search by colour, describe a picture (“drone shot over the beach”) or drop one to find clips that look like it, and where in the clip.",
                        vi: "Tab Visual: tìm theo màu, tả một bức ảnh (“drone shot over the beach”) hoặc thả một ảnh vào để tìm clip trông giống vậy, và đúng đoạn nào trong clip." },
    "find.free":      { en: "Everything else in search is free: names, spoken words, chips, Advanced and drives.",
                        vi: "Mọi thứ khác của phần tìm kiếm đều miễn phí: tên file, lời nói, chip, Advanced và ổ cắm ngoài." },
